// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 initialBalance, uint256 depositAmount) public {
        // Restrict inputs to avoid overflow on depositAmount (which is uint256) but allow overflow scenario
        vm.assume(initialBalance < type(uint256).max);
        vm.assume(depositAmount > 0);
        // Ensure initialBalance + depositAmount > type(uint256).max to trigger overflow
        vm.assume(initialBalance > type(uint256).max - depositAmount);

        // Fund user with initial balance and set balances[user] = initialBalance via deposit
        vm.deal(user, initialBalance);
        vm.prank(user);
        c.deposit{value: initialBalance}();

        // Now attempt deposit that would overflow
        vm.deal(user, depositAmount);
        vm.prank(user);
        (bool success, ) = address(c).call{value: depositAmount}(abi.encodeWithSignature("deposit()"));

        // The reference contract (with assertion) should revert; the mutant may not
        assertTrue(!success, "Deposit should revert on overflow");
    }
}

