pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 value) public {
        vm.assume(value > 1); // multiplication only differs for msg.value > 1
        vm.assume(amount <= type(uint256).max / value); // avoid overflow in multiplication
        // fund the caller with enough ether
        address caller = address(0x1234);
        vm.deal(caller, amount);
        // first deposit to set a balance
        vm.prank(caller);
        c.deposit{value: amount}();
        // get the balance after first deposit
        uint256 balanceBefore = c.balances(caller);
        // now deposit again with value
        vm.prank(caller);
        c.deposit{value: value}();
        uint256 balanceAfter = c.balances(caller);
        // In reference: balanceAfter = balanceBefore + value, so balanceAfter > balanceBefore
        // In mutant: balanceAfter = balanceBefore * value, so balanceAfter may be less than balanceBefore if balanceBefore == 0
        assertTrue(balanceAfter > balanceBefore);
    }
}

