pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        uint256 amountBounded = bound(amount, 1, 1e18);
        vm.deal(address(this), amountBounded);

        // Deposit
        c.deposit{value: amountBounded}();

        // Record balances before migrateTo
        uint256 recipientBalanceBefore = recipient.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call migrateTo as creator
        vm.prank(address(c.creator()));
        c.migrateTo(recipient);

        // Assert: recipient gained exactly the contract's previous balance
        assertTrue(recipient.balance - recipientBalanceBefore == contractBalanceBefore);
    }
}

